import { apiFetch, ApiError } from './api-client.js';

const $=(id)=>document.getElementById(id); const page=$('situationPage');
const state={me:null,list:[],working:null,savedHash:null,persisted:false,meta:null,dirty:false,mode:'select',selected:null,map:null,mapLayers:[],fallback:false,aircraft:[],resources:[],airportCatalog:[],missionCatalog:[],missionHistory:[],layers:{airports:true,missions:true,damage:true,labels:true},tempAirportIds:new Set(),candidateQuery:'',candidateRole:'',candidateRegion:'',draftMissionCoord:null,panelDraftDirty:false};
const refs={map:$('situationMap'),fallback:$('situationFallbackMap'),fallbackObjects:$('fallbackObjects'),select:$('situationSelect'),meta:$('situationMeta'),saveState:$('situationSaveState'),save:$('saveSituationButton'),del:$('deleteSituationButton'),newBtn:$('newSituationButton'),tools:document.querySelector('.situation-tools'),search:$('situationSearch'),fit:$('fitSituationButton'),inspector:$('situationInspector'),inspectorTitle:$('inspectorTitle'),inspectorSubtitle:$('inspectorSubtitle'),body:$('inspectorBody'),close:$('closeInspector'),overview:$('situationOverview'),overviewTrigger:$('overviewTrigger'),overviewCounts:$('overviewCounts'),overviewContent:$('overviewContent'),msg:$('situationMessage'),createModal:$('situationCreateModal'),newId:$('newSituationId'),newName:$('newSituationName'),newDesc:$('newSituationDescription'),newMsg:$('newSituationMessage'),newCancel:$('newSituationCancel'),newConfirm:$('newSituationConfirm'),confirmModal:$('situationConfirmModal'),confirmBody:$('situationConfirmBody'),confirmCancel:$('situationConfirmCancel'),confirmAction:$('situationConfirmAction')};
const esc=(v)=>String(v??'—').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); const val=(v)=>v==null?'':String(v); const num=(v)=>v===''||v==null?null:Number(v); const int=(v)=>v===''||v==null?null:Number.parseInt(v,10); const writable=()=>state.me?.permissions?.includes('situations.write');
function showMessage(text,type='info'){refs.msg.textContent=text;refs.msg.className=`workspace-message ${type}`;refs.msg.classList.remove('hidden');clearTimeout(showMessage.t);showMessage.t=setTimeout(()=>refs.msg.classList.add('hidden'),4200)}
function errText(e){return e instanceof ApiError?`${e.message}${e.field?`（${e.field}）`:''}`:'操作失败'} function deep(x){return JSON.parse(JSON.stringify(x))}
function setModal(el,open){el.classList.toggle('open',open);el.setAttribute('aria-hidden',open?'false':'true')}
function confirmAction(text,label='确认'){return new Promise(resolve=>{refs.confirmBody.innerHTML=`<div class="inline-message warning">${esc(text)}</div>`;refs.confirmAction.textContent=label;setModal(refs.confirmModal,true);const done=v=>{setModal(refs.confirmModal,false);refs.confirmAction.onclick=null;refs.confirmCancel.onclick=null;resolve(v)};refs.confirmAction.onclick=()=>done(true);refs.confirmCancel.onclick=()=>done(false)})}
function markDirty(){if(!state.working)return;state.dirty=true;renderHeader();renderOverview();drawMap()}
async function canonicalizeWorking(candidate){const d=await apiFetch('/api/situations/working-copy/canonicalize',{method:'POST',body:{situation:candidate}});return deep(d.situation)}
function airportItem(id){return state.working?.airports?.find(x=>x.airport.airport_id===id)} function missionItem(id){return state.working?.missions?.find(x=>x.mission_id===id)} function damageScenario(id){return state.working?.damage_scenarios?.find(x=>x.damage_scenario_id===id)}
function aircraftName(id){const x=state.aircraft.find(v=>v.aircraft_type.aircraft_type_id===id);return x?.aircraft_type?.name||id} function resourceName(id){const x=state.resources.find(v=>v.resource_type.resource_type_id===id);return x?.resource_type?.name||id}
function renderHeader(){if(!state.working){refs.meta.textContent='打开或创建情境后开始编辑';refs.saveState.textContent='未打开';refs.saveState.className='badge';refs.save.disabled=true;refs.del.disabled=true;return} refs.meta.textContent=`${state.working.situation_id}${state.meta?.updated_at?` · 最近保存 ${state.meta.updated_at}`:''}${state.meta?.historical_run_count?` · 历史 Run ${state.meta.historical_run_count}`:''}`;refs.saveState.textContent=state.persisted?(state.dirty?'未保存':'已保存'):'新建未保存';refs.saveState.className=`badge ${state.dirty||!state.persisted?'warning':'success'}`;refs.save.disabled=!writable()||(!state.dirty&&state.persisted);refs.del.disabled=!writable()||!state.persisted}
async function loadSituationList(selectId=null){const d=await apiFetch('/api/situations?limit=500&offset=0');state.list=d.items||[];refs.select.innerHTML='<option value="">选择情境…</option>'+state.list.map(x=>`<option value="${esc(x.situation_id)}">${esc(x.name)}（${esc(x.situation_id)}）</option>`).join('');if(selectId)refs.select.value=selectId}
async function canDiscard(){if(!state.dirty)return true;return confirmAction('当前情境有未保存修改。继续会丢弃这些修改。','放弃修改')}
function bindPanelDraft(){refs.body.querySelectorAll('input,select,textarea').forEach(el=>{const mark=()=>{state.panelDraftDirty=true};el.addEventListener('input',mark);el.addEventListener('change',mark)})}
async function canDiscardPanelDraft(){if(!state.panelDraftDirty)return true;return confirmAction('当前右侧表单还有尚未“应用到情境”的修改。继续会放弃这些表单修改。','放弃表单修改')}
function clearPanelDraft(){state.panelDraftDirty=false;state.draftMissionCoord=null}
async function openSituation(id){if(!id)return;if(!(await canDiscardPanelDraft())){refs.select.value=state.working?.situation_id||'';return}if(!(await canDiscard())){refs.select.value=state.working?.situation_id||'';return}try{const d=await apiFetch(`/api/situations/${encodeURIComponent(id)}`);state.working=deep(d.situation);state.savedHash=d.content_hash;state.persisted=true;state.meta=d;state.dirty=false;state.selected=null;renderAll();fitMap()}catch(e){showMessage(errText(e),'error')}}
function newSituation(){if(!writable()){showMessage('当前账号没有情境维护权限。','error');return}refs.newId.value='';refs.newName.value='';refs.newDesc.value='';refs.newMsg.classList.add('hidden');setModal(refs.createModal,true);setTimeout(()=>refs.newId.focus(),30)}
async function createWorking(){if(!(await canDiscardPanelDraft()))return;const id=refs.newId.value.trim(),name=refs.newName.value.trim();if(!id||!name){refs.newMsg.textContent='情境编号和名称不能为空。';refs.newMsg.className='inline-message error';refs.newMsg.classList.remove('hidden');return}if(!(await canDiscard()))return;clearPanelDraft();state.working={situation_id:id,name,description:refs.newDesc.value.trim()||null,airports:[],missions:[],damage_scenarios:[]};state.savedHash=null;state.persisted=false;state.meta=null;state.dirty=true;state.selected=null;refs.select.value='';setModal(refs.createModal,false);renderAll()}
async function saveSituation(){if(!state.working||!writable())return;try{let d;if(state.persisted)d=await apiFetch(`/api/situations/${encodeURIComponent(state.working.situation_id)}`,{method:'PUT',body:{situation:state.working,expected_content_hash:state.savedHash}});else d=await apiFetch('/api/situations',{method:'POST',body:{situation:state.working}});state.working=deep(d.situation);state.savedHash=d.content_hash;state.persisted=true;state.meta={...(state.meta||{}),...d};state.dirty=false;await loadSituationList(state.working.situation_id);renderAll();showMessage('情境已保存。','success')}catch(e){if(e instanceof ApiError&&e.status===409)showMessage('保存失败：服务器中的情境已经变化，请重新打开后合并修改。','error');else showMessage(errText(e),'error')}}
async function deleteSituation(){if(!state.persisted||!state.working)return;const active=state.meta?.active_run_count||0,hist=state.meta?.historical_run_count||0;if(!(await confirmAction(`删除情境 ${state.working.name}？当前关联 ${active} 个活动 Run、${hist} 个历史 Run。历史 Run 的冻结快照不会被修改；活动 Run 存在时后端可能拒绝删除。`,'删除情境')))return;try{await apiFetch(`/api/situations/${encodeURIComponent(state.working.situation_id)}`,{method:'DELETE',body:{expected_content_hash:state.savedHash}});state.working=null;state.persisted=false;state.savedHash=null;state.meta=null;state.dirty=false;state.selected=null;await loadSituationList();renderAll();showMessage('情境已删除。','success')}catch(e){showMessage(errText(e),'error')}}
function setInspectorOpen(open){refs.inspector.classList.toggle('closed',!open);page.classList.toggle('inspector-collapsed',!open)}
function collapseOverview(){refs.overview.classList.remove('open');refs.overviewTrigger.setAttribute('aria-expanded','false')}
function setMode(mode){state.mode=mode;state.selected=null;state.draftMissionCoord=null;if(mode==='airport')state.tempAirportIds=new Set();if(mode!=='layers')collapseOverview();refs.tools.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));setInspectorOpen(true);renderInspector()}
function lockEditorForReadOnly(){if(writable())return;refs.body.querySelectorAll('input,select,textarea,button').forEach(el=>{el.disabled=true});refs.inspectorSubtitle.textContent=`${refs.inspectorSubtitle.textContent} · 只读`; }
function applyPermissionUi(){const can=writable();refs.newBtn.disabled=!can;for(const mode of ['airport','mission','damage']){const b=refs.tools.querySelector(`[data-mode="${mode}"]`);if(b){b.disabled=!can;b.title=can?'':'当前账号为只读权限';}}}
function renderAll(){applyPermissionUi();renderHeader();renderOverview();renderInspector();drawMap()}
function renderOverview(){const s=state.working;const ac=s?.airports?.length||0,mc=s?.missions?.length||0,dc=s?.damage_scenarios?.length||0;refs.overviewCounts.textContent=`机场 ${ac} · 任务 ${mc} · 损毁场景 ${dc}`;if(!s){refs.overviewContent.innerHTML='<div class="empty-state">尚未打开情境。</div>';return}const col=(title,items)=>`<div class="overview-column"><h3>${title}</h3>${items.length?items.map(x=>`<div class="overview-item"><span>${esc(x[0])}</span><span>${esc(x[1])}</span></div>`).join(''):'<div class="field-note">暂无</div>'}</div>`;refs.overviewContent.innerHTML=col('机场',s.airports.map(x=>[x.airport.airport_name,x.airport.airport_id]))+col('任务',s.missions.map(x=>[x.name,x.mission_id]))+col('损毁场景',s.damage_scenarios.map(x=>[x.name,`${x.events.length} 事件`]));}
function objectCard(type,id,title,sub){return `<button class="object-card ${state.selected?.type===type&&state.selected?.id===id?'selected':''}" type="button" data-object-type="${type}" data-object-id="${esc(id)}"><span><strong>${esc(title)}</strong><small>${esc(sub)}</small></span><span>›</span></button>`}
function bindObjectCards(){refs.body.querySelectorAll('[data-object-type]').forEach(b=>b.onclick=async()=>{if(!(await canDiscardPanelDraft()))return;clearPanelDraft();state.selected={type:b.dataset.objectType,id:b.dataset.objectId};renderInspector();drawMap()})}
function modeSelect(){if(!state.working)return '<div class="empty-state">请选择或创建情境。</div>';const q=refs.search.value.trim().toLowerCase();let cards=[];for(const a of state.working.airports){const text=`${a.airport.airport_id} ${a.airport.airport_name}`.toLowerCase();if(!q||text.includes(q))cards.push(objectCard('airport',a.airport.airport_id,a.airport.airport_name,`${a.airport.airport_id} · ${a.operational_profile.capacity_per_window??'—'} /窗`))}for(const m of state.working.missions){const text=`${m.mission_id} ${m.name}`.toLowerCase();if(!q||text.includes(q))cards.push(objectCard('mission',m.mission_id,m.name,`${m.mission_id} · T${m.window_start_slot}–T${m.window_end_slot}`))}return `<div class="mode-actions"><button id="editSituationInfo" class="btn" type="button" ${writable()?'':'disabled'}>编辑情境信息</button></div><div class="object-list">${cards.join('')||'<div class="empty-state">当前情境没有匹配对象。</div>'}</div>`}
function renderInspector(){setInspectorOpen(true);if(!state.working){refs.inspectorTitle.textContent='情境对象';refs.inspectorSubtitle.textContent='选择或创建情境';refs.body.innerHTML='<div class="empty-state">尚未打开情境。</div>';return}if(state.mode==='airport'){renderAirportCandidates();return}if(state.mode==='mission'){renderMissionMode();return}if(state.mode==='damage'){renderDamageMode();return}if(state.mode==='layers'){renderLayers();return}if(state.selected?.type==='airport'){renderAirportEditor(state.selected.id);return}if(state.selected?.type==='mission'){renderMissionEditor(state.selected.id);return}refs.inspectorTitle.textContent='当前情境对象';refs.inspectorSubtitle.textContent='机场与任务属于 Working Copy；修改后统一保存';refs.body.innerHTML=modeSelect();bindObjectCards();const edit=$('editSituationInfo');if(edit)edit.onclick=renderSituationInfoEditor}
function renderSituationInfoEditor(){collapseOverview();refs.inspectorTitle.textContent='情境信息';refs.inspectorSubtitle.textContent=state.working.situation_id;refs.body.innerHTML=`<div class="compact-grid"><div class="field wide"><label>情境编号</label><input class="control" value="${esc(state.working.situation_id)}" readonly></div><div class="field wide"><label>名称</label><input id="editSituationName" class="control" value="${esc(state.working.name)}"></div><div class="field wide"><label>说明</label><textarea id="editSituationDescription" class="control textarea-control" rows="4">${esc(state.working.description||'')}</textarea></div></div><div class="inspector-footer"><button id="cancelSituationInfo" class="btn ghost" type="button">取消</button><button id="applySituationInfo" class="btn primary" type="button">应用到情境</button></div>`;bindPanelDraft();$('cancelSituationInfo').onclick=()=>{clearPanelDraft();renderInspector()};$('applySituationInfo').onclick=async()=>{const name=$('editSituationName').value.trim();if(!name){showMessage('情境名称不能为空。','error');return}try{const candidate=deep(state.working);candidate.name=name;candidate.description=$('editSituationDescription').value.trim()||null;state.working=await canonicalizeWorking(candidate);clearPanelDraft();markDirty();renderSituationInfoEditor();showMessage('情境信息已应用到 Working Copy。','success')}catch(e){showMessage(errText(e),'error')}};lockEditorForReadOnly()}
async function ensureAirportCatalog(){if(state.airportCatalog.length)return;let offset=0,total=1,out=[];while(offset<total){const d=await apiFetch(`/api/airports?limit=500&offset=${offset}`);out.push(...(d.items||[]));total=d.total||0;offset+=500}state.airportCatalog=out}
async function renderAirportCandidates(){refs.inspectorTitle.textContent='添加机场至当前情境';refs.inspectorSubtitle.textContent=`已有 ${state.working.airports.length} 个机场 · 选择后先进入未保存 Working Copy`;refs.body.innerHTML='<div class="empty-state">正在读取机场基础库…</div>';try{await ensureAirportCatalog();const existing=new Set(state.working.airports.map(x=>x.airport.airport_id));refs.body.innerHTML=`<div class="candidate-toolbar"><input id="airportCandidateSearch" class="control" placeholder="名称或编号"><select id="airportCandidateRole" class="control"><option value="">全部类型</option><option value="military">军用</option><option value="joint">军民合用</option><option value="civil">民用</option></select><select id="airportCandidateRegion" class="control"><option value="">全部区域</option>${[...new Set(state.airportCatalog.map(x=>x.region).filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b),'zh-CN')).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></div><div id="airportCandidateList" class="candidate-list"></div><div class="inspector-footer"><button id="addAirportsToSituation" class="btn primary" type="button">加入情境（0）</button></div>`;const draw=()=>{const q=$('airportCandidateSearch').value.trim().toLowerCase(),role=$('airportCandidateRole').value,region=$('airportCandidateRegion').value;state.candidateQuery=q;state.candidateRole=role;state.candidateRegion=region;const rows=state.airportCatalog.filter(x=>(!q||`${x.airport_id} ${x.airport_name}`.toLowerCase().includes(q))&&(!role||x.role===role)&&(!region||String(x.region||'')===region));$('airportCandidateList').innerHTML=rows.map(x=>{const inS=existing.has(x.airport_id),unavailable=x.configuration_complete===null,checked=state.tempAirportIds.has(x.airport_id);return `<label class="candidate-row ${inS||unavailable?'disabled':''} ${checked?'selected':''}"><input type="checkbox" value="${esc(x.airport_id)}" ${checked?'checked':''} ${inS||unavailable?'disabled':''}><span><strong>${esc(x.airport_name)}</strong><small>${esc(x.airport_id)} · ${esc(x.region||'未分区')} · ${unavailable?'无运行配置':x.configuration_complete?'配置完整':'配置未标记完整'}</small></span><span>${inS?'已加入':''}</span></label>`}).join('')||'<div class="empty-state">没有匹配机场。</div>';refs.body.querySelectorAll('#airportCandidateList input').forEach(c=>c.onchange=()=>{if(c.checked)state.tempAirportIds.add(c.value);else state.tempAirportIds.delete(c.value);updateCount();drawMap()});updateCount();drawMap()};const updateCount=()=>{const n=state.tempAirportIds.size;$('addAirportsToSituation').textContent=`加入情境（${n}）`};$('airportCandidateSearch').oninput=draw;$('airportCandidateRole').onchange=draw;$('airportCandidateRegion').onchange=draw;$('addAirportsToSituation').onclick=addSelectedAirports;draw()}catch(e){refs.body.innerHTML=`<div class="inline-message error">${esc(errText(e))}</div>`}}
async function addSelectedAirports(){const ids=[...state.tempAirportIds];if(!ids.length)return;try{let s=state.working;for(const id of ids){const d=await apiFetch('/api/situations/working-copy/copy-airport',{method:'POST',body:{situation:s,airport_id:id}});s=d.situation}state.working=deep(s);state.tempAirportIds=new Set();markDirty();renderAirportCandidates();showMessage(`已加入 ${ids.length} 个机场，尚未保存。`,'success')}catch(e){showMessage(errText(e),'error')}}
function opt(items,current,getId,getName){return `<option value="">请选择…</option>${items.map(x=>{const id=getId(x),name=getName(x);return `<option value="${esc(id)}" ${String(id)===String(current)?'selected':''}>${esc(name)}（${esc(id)}）</option>`}).join('')}`}
function supportRow(r={}){return `<div class="dynamic-row support-row"><div class="field"><label>机型</label><select class="control row-aircraft">${opt(state.aircraft,r.aircraft_type_id,x=>x.aircraft_type.aircraft_type_id,x=>x.aircraft_type.name)}</select></div><div class="field"><label>数量</label><input class="control row-initial" type="number" min="0" value="${esc(val(r.initial_quantity))}"></div><div class="field"><label>整备/窗</label><input class="control row-reset" type="number" min="0" value="${esc(val(r.tau_reset_windows))}"></div><button class="mini-button remove-row" type="button">×</button></div>`}
