function replenishRow(r={}){return `<div class="dynamic-row replenish-row"><div class="field"><label>资源</label><select class="control row-resource">${opt(state.resources,r.resource_type_id,x=>x.resource_type.resource_type_id,x=>x.resource_type.name)}</select></div><div class="field"><label>时间窗</label><input class="control row-slot" type="number" min="0" value="${esc(val(r.slot))}"></div><div class="field"><label>实际补给</label><input class="control row-qty" type="number" min="0" step="any" value="${esc(val(r.quantity))}"></div><button class="mini-button remove-row" type="button">×</button></div>`}
function bindDynamic(addId,target,fn){const b=$(addId);if(b)b.onclick=()=>{state.panelDraftDirty=true;$(target).insertAdjacentHTML('beforeend',fn({}));bindRemoves()};bindRemoves()}function bindRemoves(){refs.body.querySelectorAll('.remove-row').forEach(b=>b.onclick=()=>{state.panelDraftDirty=true;b.closest('.dynamic-row').remove()})}
function renderAirportEditor(id){collapseOverview();const x=airportItem(id);if(!x)return;const a=x.airport,p=x.operational_profile;refs.inspectorTitle.textContent=a.airport_name;refs.inspectorSubtitle.textContent=`${a.airport_id} · 情境机场配置`;refs.body.innerHTML=`<div class="compact-grid"><div class="field wide"><label>基础信息</label><div class="field-note">${esc(a.role)} · ${esc(a.region||'—')} · ${a.longitude}, ${a.latitude} · 基础字段只读</div></div><div class="field"><label>保障等级</label><input id="sitSupportLevel" class="control" value="${esc(val(p.support_level))}"></div><div class="field"><label>单时间窗起降容量</label><input id="sitCapacity" class="control" type="number" min="0" value="${esc(val(p.capacity_per_window))}"></div><div class="field wide"><label><input id="sitConfigComplete" type="checkbox" ${p.configuration_complete?'checked':''}> 配置完整</label></div></div><div class="inspector-section"><h3>支持机型及当前数量</h3><div id="sitSupportRows">${(p.aircraft_support||[]).map(supportRow).join('')}</div><button id="sitAddSupport" class="btn ghost" type="button">+ 添加机型</button></div><div class="inspector-section"><h3>资源库存与补给能力</h3><div id="sitStockRows">${(p.resource_stocks||[]).map(stockRow).join('')}</div><button id="sitAddStock" class="btn ghost" type="button">+ 添加资源</button></div><div class="inspector-section"><h3>本情境实际补给计划</h3><div id="sitReplenishRows">${(x.resource_replenishments||[]).map(replenishRow).join('')}</div><button id="sitAddReplenish" class="btn ghost" type="button">+ 添加补给</button></div><div id="sitAirportMsg" class="inline-message hidden"></div><div class="inspector-footer"><button id="cancelAirportEdit" class="btn ghost" type="button">取消</button><a class="btn" href="/base-data?tab=airports&id=${encodeURIComponent(a.airport_id)}">查看基础数据</a><button id="restoreAirportBase" class="btn" type="button">恢复基础配置</button><button id="removeAirport" class="btn danger" type="button">移出情境</button><button id="applyAirport" class="btn primary" type="button">应用到情境</button></div>`;bindDynamic('sitAddSupport','sitSupportRows',supportRow);bindDynamic('sitAddStock','sitStockRows',stockRow);bindDynamic('sitAddReplenish','sitReplenishRows',replenishRow);bindPanelDraft();$('cancelAirportEdit').onclick=()=>{clearPanelDraft();setMode('select')};$('applyAirport').onclick=applyAirport;$('removeAirport').onclick=removeAirport;$('restoreAirportBase').onclick=restoreAirportBase;lockEditorForReadOnly();}
function collectRows(sel,fn){return [...refs.body.querySelectorAll(sel)].map(fn)}
async function applyAirport(){try{const candidate=deep(state.working);const x=candidate.airports.find(v=>v.airport.airport_id===state.selected.id);if(!x)return;x.operational_profile={...x.operational_profile,configuration_complete:$('sitConfigComplete').checked,capacity_per_window:int($('sitCapacity').value),support_level:$('sitSupportLevel').value.trim()||null,aircraft_support:collectRows('.support-row',r=>({aircraft_type_id:r.querySelector('.row-aircraft').value,initial_quantity:int(r.querySelector('.row-initial').value),tau_reset_windows:int(r.querySelector('.row-reset').value)})),resource_stocks:collectRows('.stock-row',r=>({resource_type_id:r.querySelector('.row-resource').value,initial_quantity:num(r.querySelector('.row-stock').value),replenishment_capacity_per_window:num(r.querySelector('.row-cap').value)}))};x.resource_replenishments=collectRows('.replenish-row',r=>({resource_type_id:r.querySelector('.row-resource').value,slot:int(r.querySelector('.row-slot').value),quantity:num(r.querySelector('.row-qty').value)}));state.working=await canonicalizeWorking(candidate);clearPanelDraft();markDirty();showMessage('机场配置已应用到 Working Copy，尚未保存。','success');renderInspector()}catch(e){showMessage(errText(e),'error')}}
async function restoreAirportBase(){if(!(await confirmAction('恢复会用当前 Base Data 的机场及运行配置替换该情境机场配置；现有本情境补给安排也会被清除。','恢复基础配置')))return;try{const d=await apiFetch('/api/situations/working-copy/copy-airport',{method:'POST',body:{situation:state.working,airport_id:state.selected.id}});state.working=deep(d.situation);clearPanelDraft();markDirty();renderInspector();showMessage('已恢复基础配置，尚未保存。','success')}catch(e){showMessage(errText(e),'error')}}
async function removeAirport(){const id=state.selected.id;const refsDamage=state.working.damage_scenarios.flatMap(s=>s.events).filter(e=>e.target.airport_id===id);if(refsDamage.length){showMessage(`该机场仍被 ${refsDamage.length} 个损毁事件引用，请先删除相关事件。`,'error');return}if(!(await confirmAction(`从当前情境移除机场 ${id}？只影响 Working Copy，不删除 Base Data。`,'移出情境')))return;state.working.airports=state.working.airports.filter(x=>x.airport.airport_id!==id);clearPanelDraft();state.selected=null;markDirty();renderInspector()}
async function ensureMissionData(){if(!state.missionCatalog.length){let offset=0,total=1,out=[];while(offset<total){const d=await apiFetch(`/api/missions?limit=500&offset=${offset}`);out.push(...(d.items||[]));total=d.total||0;offset+=500}state.missionCatalog=out}if(!state.missionHistory.length){const h=await apiFetch('/api/missions/history?limit=500');state.missionHistory=h.items||[]}}
async function renderMissionMode(){refs.inspectorTitle.textContent='任务';refs.inspectorSubtitle.textContent='新建、从模板或历史 Run 复制到当前 Working Copy';refs.body.innerHTML='<div class="empty-state">正在读取任务来源…</div>';try{await ensureMissionData();refs.body.innerHTML=`<div class="mode-actions"><button id="newMissionAction" class="btn primary" type="button">新建任务</button></div><div class="inspector-section"><h3>任务模板</h3><div class="object-list">${state.missionCatalog.map(x=>objectCard('template',x.mission.mission_id,x.mission.name,`${x.mission.mission_id} · T${x.mission.window_start_slot}–T${x.mission.window_end_slot}`)).join('')||'<div class="field-note">暂无任务模板。</div>'}</div></div><div class="inspector-section"><h3>历史任务</h3><div class="object-list">${state.missionHistory.slice(0,50).map((x,i)=>objectCard('history',String(i),x.mission.name,`${x.mission.mission_id} · ${x.source_run_id}`)).join('')||'<div class="field-note">暂无历史任务。</div>'}</div></div>`;$('newMissionAction').onclick=()=>renderMissionEditor(null);refs.body.querySelectorAll('[data-object-type="template"]').forEach(b=>b.onclick=()=>copyMissionTemplate(b.dataset.objectId));refs.body.querySelectorAll('[data-object-type="history"]').forEach(b=>b.onclick=()=>copyHistoricalMission(Number(b.dataset.objectId)))}catch(e){refs.body.innerHTML=`<div class="inline-message error">${esc(errText(e))}</div>`}}
async function copyMissionTemplate(id){if(state.working.missions.some(x=>x.mission_id===id)){showMessage('当前情境已存在同编号任务。','error');return}try{const d=await apiFetch('/api/situations/working-copy/copy-mission',{method:'POST',body:{situation:state.working,mission_id:id}});state.working=deep(d.situation);markDirty();showMessage('任务模板已复制到情境，尚未保存。','success');renderMissionMode()}catch(e){showMessage(errText(e),'error')}}
async function copyHistoricalMission(index){const m=state.missionHistory[index]?.mission;if(!m)return;if(state.working.missions.some(x=>x.mission_id===m.mission_id)){showMessage('当前情境已存在同编号任务；可先打开已有任务编辑。','error');return}try{const d=await apiFetch('/api/situations/working-copy/copy-mission',{method:'POST',body:{situation:state.working,mission:m}});state.working=deep(d.situation);markDirty();showMessage('历史任务快照已复制到情境。','success');renderMissionMode()}catch(e){showMessage(errText(e),'error')}}
function missionReqRow(r={}){return `<div class="dynamic-row mission-req"><div class="field"><label>机型</label><select class="control row-aircraft">${opt(state.aircraft,r.aircraft_type_id,x=>x.aircraft_type.aircraft_type_id,x=>x.aircraft_type.name)}</select></div><div class="field"><label>架次</label><input class="control row-sorties" type="number" min="1" value="${esc(val(r.required_sorties))}"></div><div class="field"><label>作业/窗</label><input class="control row-work" type="number" min="0" value="${esc(val(r.tau_work_windows))}"></div><button class="mini-button remove-row" type="button">×</button></div>`}
function renderMissionEditor(id){collapseOverview();const m=id?missionItem(id):{mission_id:'',name:'',longitude:'',latitude:'',window_start_slot:0,window_end_slot:1,aircraft_requirements:[]};refs.inspectorTitle.textContent=id?m.name:'新建任务';refs.inspectorSubtitle.textContent=id?`${m.mission_id} · 情境任务快照`:'新任务只进入当前 Working Copy';refs.body.innerHTML=`<div class="compact-grid"><div class="field"><label>任务编号</label><input id="sitMissionId" class="control" value="${esc(m.mission_id)}" ${id?'readonly':''}></div><div class="field"><label>名称</label><input id="sitMissionName" class="control" value="${esc(m.name)}"></div><div class="field"><label>经度</label><input id="sitMissionLon" class="control" type="number" step="any" value="${esc(val(m.longitude))}"></div><div class="field"><label>纬度</label><input id="sitMissionLat" class="control" type="number" step="any" value="${esc(val(m.latitude))}"></div><div class="field wide"><button id="pickMissionLocation" class="btn ghost" type="button">从地图取点</button><span class="field-note">输入坐标会同步临时位置预览；正式地图内核存在时可直接点选。</span></div><div class="field"><label>开始窗</label><input id="sitMissionStart" class="control" type="number" min="0" value="${esc(val(m.window_start_slot))}"></div><div class="field"><label>结束窗（不含）</label><input id="sitMissionEnd" class="control" type="number" min="1" value="${esc(val(m.window_end_slot))}"></div></div><div class="inspector-section"><h3>各机型需求</h3><div id="sitMissionReqs">${(m.aircraft_requirements||[]).map(missionReqRow).join('')}</div><button id="sitAddMissionReq" class="btn ghost" type="button">+ 添加机型需求</button></div><div class="inspector-footer"><button id="cancelMissionEdit" class="btn ghost" type="button">取消</button>${id?'<button id="removeMission" class="btn danger" type="button">移出情境</button>':''}<button id="applyMission" class="btn primary" type="button">${id?'应用到情境':'加入情境'}</button></div>`;bindDynamic('sitAddMissionReq','sitMissionReqs',missionReqRow);const syncDraft=()=>{const lonRaw=$('sitMissionLon').value.trim(),latRaw=$('sitMissionLat').value.trim();const lon=lonRaw===''?null:Number(lonRaw),lat=latRaw===''?null:Number(latRaw);state.draftMissionCoord=Number.isFinite(lon)&&Number.isFinite(lat)?{lon,lat}:null;drawMap()};$('sitMissionLon').oninput=syncDraft;$('sitMissionLat').oninput=syncDraft;state.draftMissionCoord=(m.longitude===''||m.longitude==null||m.latitude===''||m.latitude==null)?null:{lon:Number(m.longitude),lat:Number(m.latitude)};bindPanelDraft();$('cancelMissionEdit').onclick=()=>{clearPanelDraft();setMode('select')};$('pickMissionLocation').onclick=beginMissionLocationPick;$('applyMission').onclick=()=>applyMission(id);if(id)$('removeMission').onclick=()=>removeMission(id);lockEditorForReadOnly()}
function beginMissionLocationPick(){if(state.fallback||!state.map){showMessage('本地 Leaflet 尚未放置，当前请手动输入经纬度；输入值仍会更新无底图预览。','error');return}const b=$('pickMissionLocation');b.textContent='请在地图点击位置…';state.map.once('click',e=>{$('sitMissionLon').value=e.latlng.lng.toFixed(6);$('sitMissionLat').value=e.latlng.lat.toFixed(6);state.draftMissionCoord={lon:e.latlng.lng,lat:e.latlng.lat};b.textContent='从地图取点';drawMap()})}
async function applyMission(oldId){const id=$('sitMissionId').value.trim(),name=$('sitMissionName').value.trim();if(!id||!name){showMessage('任务编号和名称不能为空。','error');return}if(!oldId&&state.working.missions.some(x=>x.mission_id===id)){showMessage('当前情境已存在同编号任务。','error');return}try{const candidate=deep(state.working);const m={mission_id:id,name,longitude:num($('sitMissionLon').value),latitude:num($('sitMissionLat').value),window_start_slot:int($('sitMissionStart').value),window_end_slot:int($('sitMissionEnd').value),aircraft_requirements:collectRows('.mission-req',r=>({aircraft_type_id:r.querySelector('.row-aircraft').value,required_sorties:int(r.querySelector('.row-sorties').value),tau_work_windows:int(r.querySelector('.row-work').value)}))};if(oldId)candidate.missions=candidate.missions.map(x=>x.mission_id===oldId?m:x);else candidate.missions.push(m);state.working=await canonicalizeWorking(candidate);clearPanelDraft();state.selected={type:'mission',id};markDirty();renderMissionEditor(id);showMessage('任务已应用到 Working Copy。','success')}catch(e){showMessage(errText(e),'error')}}
async function removeMission(id){if(!(await confirmAction(`从当前情境移除任务 ${id}？`,'移出情境')))return;state.working.missions=state.working.missions.filter(x=>x.mission_id!==id);clearPanelDraft();state.selected=null;markDirty();setMode('select')}
function renderDamageMode(){refs.inspectorTitle.textContent='损毁场景';refs.inspectorSubtitle.textContent='事件只作用于当前情境机场；不提供内部算法系数';refs.body.innerHTML=`<div class="mode-actions"><button id="newDamageScenario" class="btn primary" type="button">新建损毁场景</button></div><div class="object-list">${state.working.damage_scenarios.map(s=>objectCard('damage',s.damage_scenario_id,s.name,`${s.category} · ${s.events.length} 个事件`)).join('')||'<div class="empty-state">当前情境还没有损毁场景。</div>'}</div>`;$('newDamageScenario').onclick=()=>renderDamageEditor(null);refs.body.querySelectorAll('[data-object-type="damage"]').forEach(b=>b.onclick=()=>renderDamageEditor(b.dataset.objectId))}
function damageEventRow(e={},idx=0){const t=e.damage_type||'capacity_damage',airport=e.target?.airport_id||'',rec=e.recovery_mode||'instant';let effect='';if(t==='capacity_damage'){effect=`<div class="damage-effect-grid"><div class="field"><label>剩余容量/窗</label><input class="control ev-cap" type="number" min="0" value="${esc(val(e.effect?.remaining_capacity_per_window??0))}"></div><div class="field"><label>关闭</label><select class="control ev-closed"><option value="false" ${e.effect?.closed?'':'selected'}>否</option><option value="true" ${e.effect?.closed?'selected':''}>是</option></select></div></div>`}else if(t==='navigation_delay'){effect=`<div class="damage-effect-grid"><div class="field"><label>离场延迟/窗</label><input class="control ev-dep-delay" type="number" min="0" value="${esc(val(e.effect?.departure_delay_slots??0))}"></div><div class="field"><label>返航延迟/窗</label><input class="control ev-ret-delay" type="number" min="0" value="${esc(val(e.effect?.return_delay_slots??0))}"></div></div>`}else if(t==='aircraft_damage'){const entries=Object.entries(e.effect?.aircraft_loss||{});effect=`<div class="effect-rows aircraft-loss-rows">${(entries.length?entries:[['',1]]).map(([id,q])=>`<div class="damage-effect-grid effect-row"><select class="control loss-aircraft">${opt(state.aircraft,id,x=>x.aircraft_type.aircraft_type_id,x=>x.aircraft_type.name)}</select><input class="control loss-qty" type="number" min="1" value="${esc(val(q))}"></div>`).join('')}</div><button class="btn ghost add-loss-row" type="button">+ 机型损失</button>`}else{const entries=Object.entries(e.effect?.remaining_quantity||{});effect=`<div class="effect-rows resource-loss-rows">${(entries.length?entries:[['',0]]).map(([id,q])=>`<div class="damage-effect-grid effect-row"><select class="control loss-resource">${opt(state.resources,id,x=>x.resource_type.resource_type_id,x=>x.resource_type.name)}</select><input class="control loss-qty" type="number" min="0" step="any" value="${esc(val(q))}"></div>`).join('')}</div><button class="btn ghost add-resource-row" type="button">+ 资源余量</button>`}return `<div class="damage-event" data-event-index="${idx}"><div class="damage-event-head"><strong>事件 ${idx+1}</strong><button class="mini-button remove-event" type="button">×</button></div><div class="compact-grid"><div class="field"><label>事件编号</label><input class="control ev-id" value="${esc(e.event_id||`E${idx+1}`)}"></div><div class="field"><label>顺序</label><input class="control ev-seq" type="number" min="0" value="${esc(val(e.sequence??idx))}"></div><div class="field wide"><label>目标机场</label><select class="control ev-airport">${opt(state.working.airports,airport,x=>x.airport.airport_id,x=>x.airport.airport_name)}</select></div><div class="field"><label>类型</label><select class="control ev-type"><option value="capacity_damage" ${t==='capacity_damage'?'selected':''}>起降能力变化</option><option value="resource_damage" ${t==='resource_damage'?'selected':''}>资源变化</option><option value="navigation_delay" ${t==='navigation_delay'?'selected':''}>调度延迟</option><option value="aircraft_damage" ${t==='aircraft_damage'?'selected':''}>初始航空器损失</option></select></div><div class="field"><label>恢复</label><select class="control ev-recovery" ${t==='aircraft_damage'?'disabled':''}><option value="instant" ${rec==='instant'?'selected':''}>结束后立即恢复</option><option value="average" ${rec==='average'?'selected':''}>平均恢复</option><option value="none" ${rec==='none'?'selected':''}>不恢复</option></select></div><div class="field"><label>开始窗</label><input class="control ev-start" type="number" min="0" value="${esc(val(e.start_slot??0))}"></div><div class="field"><label>结束窗（不含）</label><input class="control ev-end" type="number" min="1" value="${esc(val(e.end_slot??1))}"></div><div class="field wide"><label>平均恢复时长/窗</label><input class="control ev-duration" type="number" min="1" value="${esc(val(e.recovery_duration_slots))}" ${rec==='average'?'':'disabled'}></div></div><div class="inspector-section effect-editor">${effect}</div></div>`}
function renderDamageEditor(id){collapseOverview();const s=id?deep(damageScenario(id)):{damage_scenario_id:'',name:'',category:'custom',events:[]};refs.inspectorTitle.textContent=id?s.name:'新建损毁场景';refs.inspectorSubtitle.textContent='机场级事件；跑道/保障要素 target_id 不在前端虚构';refs.body.innerHTML=`<div class="compact-grid"><div class="field"><label>场景编号</label><input id="damageScenarioId" class="control" value="${esc(s.damage_scenario_id)}" ${id?'readonly':''}></div><div class="field"><label>名称</label><input id="damageScenarioName" class="control" value="${esc(s.name)}"></div><div class="field wide"><label>分类</label><select id="damageScenarioCategory" class="control"><option value="low" ${s.category==='low'?'selected':''}>低</option><option value="medium" ${s.category==='medium'?'selected':''}>中</option><option value="high" ${s.category==='high'?'selected':''}>高</option><option value="custom" ${s.category==='custom'?'selected':''}>自定义</option></select></div></div><div class="inspector-section"><div class="mode-actions"><button id="addDamageEvent" class="btn ghost" type="button">+ 添加事件</button></div><div id="damageEventRows">${s.events.map(damageEventRow).join('')}</div></div><div class="inspector-footer"><button id="cancelDamageEdit" class="btn ghost" type="button">取消</button>${id?'<button id="removeDamageScenario" class="btn danger" type="button">删除场景</button>':''}<button id="applyDamageScenario" class="btn primary" type="button">应用到情境</button></div>`;bindDamageEvents();bindPanelDraft();$('cancelDamageEdit').onclick=()=>{clearPanelDraft();renderDamageMode()};$('addDamageEvent').onclick=()=>{state.panelDraftDirty=true;$('damageEventRows').insertAdjacentHTML('beforeend',damageEventRow({},refs.body.querySelectorAll('.damage-event').length));bindDamageEvents()};$('applyDamageScenario').onclick=()=>applyDamageScenario(id);if(id)$('removeDamageScenario').onclick=async()=>{if(await confirmAction(`删除损毁场景 ${id}？`,'删除场景')){state.working.damage_scenarios=state.working.damage_scenarios.filter(x=>x.damage_scenario_id!==id);clearPanelDraft();markDirty();renderDamageMode()}};lockEditorForReadOnly()}
function bindDamageEvents(){refs.body.querySelectorAll('.remove-event').forEach(b=>b.onclick=()=>{state.panelDraftDirty=true;b.closest('.damage-event').remove()});refs.body.querySelectorAll('.ev-type').forEach(s=>s.onchange=()=>{const card=s.closest('.damage-event');const ev={event_id:card.querySelector('.ev-id').value,sequence:int(card.querySelector('.ev-seq').value),target:{airport_id:card.querySelector('.ev-airport').value,target_type:'airport',target_id:null},damage_type:s.value,start_slot:int(card.querySelector('.ev-start').value),end_slot:int(card.querySelector('.ev-end').value),effect:{},recovery_mode:s.value==='aircraft_damage'?'none':'instant',recovery_duration_slots:null};card.outerHTML=damageEventRow(ev,Number(card.dataset.eventIndex));bindDamageEvents();bindPanelDraft()});refs.body.querySelectorAll('.ev-recovery').forEach(s=>s.onchange=()=>{const input=s.closest('.damage-event').querySelector('.ev-duration');input.disabled=s.value!=='average';if(input.disabled)input.value=''});refs.body.querySelectorAll('.add-loss-row').forEach(b=>b.onclick=()=>{state.panelDraftDirty=true;b.previousElementSibling.insertAdjacentHTML('beforeend',`<div class="damage-effect-grid effect-row"><select class="control loss-aircraft">${opt(state.aircraft,'',x=>x.aircraft_type.aircraft_type_id,x=>x.aircraft_type.name)}</select><input class="control loss-qty" type="number" min="1" value="1"></div>`)});refs.body.querySelectorAll('.add-resource-row').forEach(b=>b.onclick=()=>{state.panelDraftDirty=true;b.previousElementSibling.insertAdjacentHTML('beforeend',`<div class="damage-effect-grid effect-row"><select class="control loss-resource">${opt(state.resources,'',x=>x.resource_type.resource_type_id,x=>x.resource_type.name)}</select><input class="control loss-qty" type="number" min="0" step="any" value="0"></div>`)});}
function eventFromCard(card){const type=card.querySelector('.ev-type').value;let effect;if(type==='capacity_damage'){const closed=card.querySelector('.ev-closed').value==='true';effect={closed,remaining_capacity_per_window:closed?0:int(card.querySelector('.ev-cap').value)}}else if(type==='navigation_delay'){effect={departure_delay_slots:int(card.querySelector('.ev-dep-delay').value)||0,return_delay_slots:int(card.querySelector('.ev-ret-delay').value)||0}}else if(type==='aircraft_damage'){const loss={};card.querySelectorAll('.effect-row').forEach(r=>{const id=r.querySelector('.loss-aircraft').value;if(id)loss[id]=int(r.querySelector('.loss-qty').value)});effect={aircraft_loss:loss}}else{const rem={};card.querySelectorAll('.effect-row').forEach(r=>{const id=r.querySelector('.loss-resource').value;if(id)rem[id]=Number(r.querySelector('.loss-qty').value)});effect={remaining_quantity:rem}}const recovery=type==='aircraft_damage'?'none':card.querySelector('.ev-recovery').value;return {event_id:card.querySelector('.ev-id').value.trim(),sequence:int(card.querySelector('.ev-seq').value),target:{airport_id:card.querySelector('.ev-airport').value,target_type:'airport',target_id:null},damage_type:type,start_slot:int(card.querySelector('.ev-start').value),end_slot:int(card.querySelector('.ev-end').value),effect,recovery_mode:recovery,recovery_duration_slots:recovery==='average'?int(card.querySelector('.ev-duration').value):null}}
async function applyDamageScenario(oldId){const id=$('damageScenarioId').value.trim(),name=$('damageScenarioName').value.trim();if(!id||!name){showMessage('损毁场景编号和名称不能为空。','error');return}if(!oldId&&state.working.damage_scenarios.some(x=>x.damage_scenario_id===id)){showMessage('当前情境已存在同编号损毁场景。','error');return}try{const candidate=deep(state.working);const scenario={damage_scenario_id:id,name,category:$('damageScenarioCategory').value,events:[...refs.body.querySelectorAll('.damage-event')].map(eventFromCard)};if(oldId)candidate.damage_scenarios=candidate.damage_scenarios.map(x=>x.damage_scenario_id===oldId?scenario:x);else candidate.damage_scenarios.push(scenario);state.working=await canonicalizeWorking(candidate);clearPanelDraft();markDirty();showMessage('损毁场景已应用到 Working Copy。','success');renderDamageEditor(id)}catch(e){showMessage(errText(e),'error')}}
function renderLayers(){refs.inspectorTitle.textContent='图层';refs.inspectorSubtitle.textContent='只控制显示，不改变情境数据';refs.body.innerHTML=`<div class="layer-list"><label><input type="checkbox" data-layer="airports" ${state.layers.airports?'checked':''}> 机场</label><label><input type="checkbox" data-layer="missions" ${state.layers.missions?'checked':''}> 任务点</label><label><input type="checkbox" data-layer="damage" ${state.layers.damage?'checked':''}> 损毁状态</label><label><input type="checkbox" data-layer="labels" ${state.layers.labels?'checked':''}> 对象标签</label></div><div class="field-note" style="margin-top:12px">情境编辑状态不绘制全图 OD 关系；完整 OD 仅在只读运行态势中展示。</div>`;refs.body.querySelectorAll('[data-layer]').forEach(c=>c.onchange=()=>{state.layers[c.dataset.layer]=c.checked;drawMap()})}
async function ensureLeaflet(){if(globalThis.L)return true;try{await new Promise((res,rej)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='/static/vendor/leaflet/leaflet.css';document.head.append(css);const js=document.createElement('script');js.src='/static/vendor/leaflet/leaflet.js';js.onload=res;js.onerror=rej;document.head.append(js)});return Boolean(globalThis.L)}catch(_){return false}}
function clearMap(){for(const l of state.mapLayers)l.remove?.();state.mapLayers=[];refs.fallbackObjects.innerHTML=''}
function damagedAirports(){return new Set((state.working?.damage_scenarios||[]).flatMap(s=>s.events||[]).map(e=>e.target?.airport_id).filter(Boolean))}
function visibleCandidateAirports(){if(state.mode!=='airport')return[];const existing=new Set((state.working?.airports||[]).map(x=>x.airport.airport_id));return state.airportCatalog.filter(x=>!existing.has(x.airport_id)&&(!state.candidateQuery||`${x.airport_id} ${x.airport_name}`.toLowerCase().includes(state.candidateQuery))&&(!state.candidateRole||x.role===state.candidateRole)&&(!state.candidateRegion||String(x.region||'')===state.candidateRegion))}
function toggleCandidate(id){const row=state.airportCatalog.find(x=>x.airport_id===id);if(!row||row.configuration_complete===null)return;if(state.tempAirportIds.has(id))state.tempAirportIds.delete(id);else state.tempAirportIds.add(id);const input=refs.body.querySelector(`#airportCandidateList input[value="${CSS.escape(id)}"]`);if(input){input.checked=state.tempAirportIds.has(id);input.closest('.candidate-row')?.classList.toggle('selected',input.checked)}const add=$('addAirportsToSituation');if(add)add.textContent=`加入情境（${state.tempAirportIds.size}）`;drawMap()}
async function selectObject(type,id){if(!(await canDiscardPanelDraft()))return;clearPanelDraft();collapseOverview();state.mode='select';refs.tools.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode==='select'));state.selected={type,id};renderInspector();drawMap()}
function drawLeaflet(){clearMap();if(!state.map||!state.working)return;const L=globalThis.L,dam=damagedAirports();if(state.layers.airports)for(const x of state.working.airports){const a=x.airport;if(!Number.isFinite(Number(a.latitude))||!Number.isFinite(Number(a.longitude)))continue;const icon=L.divIcon({className:`situation-airport-marker${state.selected?.type==='airport'&&state.selected.id===a.airport_id?' selected':''}`,html:'<div></div>',iconSize:[16,16],iconAnchor:[8,8]});const m=L.marker([a.latitude,a.longitude],{icon,title:state.layers.labels?a.airport_name:''});m.on('click',()=>selectObject('airport',a.airport_id));m.addTo(state.map);state.mapLayers.push(m);if(state.layers.damage&&dam.has(a.airport_id)){const ring=L.circleMarker([a.latitude,a.longitude],{radius:12,color:'#dd6666',weight:1.5,fillOpacity:0});ring.addTo(state.map);state.mapLayers.push(ring)}}if(state.mode==='airport')for(const x of visibleCandidateAirports()){if(!Number.isFinite(Number(x.latitude))||!Number.isFinite(Number(x.longitude)))continue;const unavailable=x.configuration_complete===null,chosen=state.tempAirportIds.has(x.airport_id);const icon=L.divIcon({className:`situation-candidate-marker${chosen?' selected':''}${unavailable?' unavailable':''}`,html:'<div></div>',iconSize:[14,14],iconAnchor:[7,7]});const m=L.marker([x.latitude,x.longitude],{icon,title:state.layers.labels?x.airport_name:''});if(!unavailable)m.on('click',()=>toggleCandidate(x.airport_id));m.addTo(state.map);state.mapLayers.push(m)}if(state.layers.missions)for(const x of state.working.missions){const icon=L.divIcon({className:'situation-mission-marker',html:'<div></div>',iconSize:[14,14],iconAnchor:[7,7]});const m=L.marker([x.latitude,x.longitude],{icon,title:state.layers.labels?x.name:''});m.on('click',()=>selectObject('mission',x.mission_id));m.addTo(state.map);state.mapLayers.push(m)}if(state.draftMissionCoord&&Number.isFinite(state.draftMissionCoord.lat)&&Number.isFinite(state.draftMissionCoord.lon)){const icon=L.divIcon({className:'situation-mission-marker draft',html:'<div></div>',iconSize:[16,16],iconAnchor:[8,8]});const m=L.marker([state.draftMissionCoord.lat,state.draftMissionCoord.lon],{icon,interactive:false});m.addTo(state.map);state.mapLayers.push(m)}}
function fallbackPoints(){if(!state.working)return[];return [...(state.layers.airports?state.working.airports.map(x=>({type:'airport',id:x.airport.airport_id,name:x.airport.airport_name,lat:Number(x.airport.latitude),lon:Number(x.airport.longitude)})):[]),...visibleCandidateAirports().map(x=>({type:'candidate',id:x.airport_id,name:x.airport_name,lat:Number(x.latitude),lon:Number(x.longitude),unavailable:x.configuration_complete===null,chosen:state.tempAirportIds.has(x.airport_id)})),...(state.layers.missions?state.working.missions.map(x=>({type:'mission',id:x.mission_id,name:x.name,lat:Number(x.latitude),lon:Number(x.longitude)})):[]),...(state.draftMissionCoord?[{type:'draft',id:'draft-mission',name:'任务临时位置',lat:state.draftMissionCoord.lat,lon:state.draftMissionCoord.lon}]:[])]}
function drawFallback(){refs.fallback.classList.remove('hidden');refs.map.classList.add('hidden');const pts=fallbackPoints().filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon));if(!pts.length){refs.fallbackObjects.innerHTML='';return}let minLat=Math.min(...pts.map(p=>p.lat)),maxLat=Math.max(...pts.map(p=>p.lat)),minLon=Math.min(...pts.map(p=>p.lon)),maxLon=Math.max(...pts.map(p=>p.lon));if(maxLat===minLat){maxLat+=1;minLat-=1}if(maxLon===minLon){maxLon+=1;minLon-=1}const dam=damagedAirports();refs.fallbackObjects.innerHTML=pts.map(p=>{const left=10+80*(p.lon-minLon)/(maxLon-minLon),top=12+76*(maxLat-p.lat)/(maxLat-minLat),damage=p.type==='airport'&&state.layers.damage&&dam.has(p.id);return `<button class="fallback-object ${p.type} ${damage?'damage':''} ${p.chosen?'selected':''} ${p.unavailable?'unavailable':''}" style="left:${left}%;top:${top}%" data-type="${p.type}" data-id="${esc(p.id)}" title="${esc(p.name)}">${state.layers.labels?`<span class="fallback-label">${esc(p.name)}</span>`:''}</button>`}).join('');refs.fallbackObjects.querySelectorAll('button').forEach(b=>b.onclick=()=>b.dataset.type==='candidate'?toggleCandidate(b.dataset.id):b.dataset.type==='draft'?null:selectObject(b.dataset.type,b.dataset.id))}
function drawMap(){if(state.fallback){drawFallback();return}drawLeaflet()}
function fitMap(){if(state.fallback||!state.map||!state.working)return;const coords=[...state.working.airports.map(x=>[Number(x.airport.latitude),Number(x.airport.longitude)]),...state.working.missions.map(x=>[Number(x.latitude),Number(x.longitude)])].filter(x=>x.every(Number.isFinite));if(coords.length)state.map.fitBounds(globalThis.L.latLngBounds(coords).pad(.12))}
async function initMap(){if(await ensureLeaflet()){state.fallback=false;refs.fallback.classList.add('hidden');refs.map.classList.remove('hidden');state.map=globalThis.L.map(refs.map,{attributionControl:false,zoomControl:true});const t=page.dataset.tileTemplate;if(t)globalThis.L.tileLayer(t,{maxZoom:12,minZoom:2,noWrap:true}).addTo(state.map);state.map.setView([34,108],4);drawMap()}else{state.fallback=true;drawFallback()}}
function bind(){refs.select.onchange=()=>openSituation(refs.select.value);refs.newBtn.onclick=newSituation;refs.newCancel.onclick=()=>setModal(refs.createModal,false);refs.newConfirm.onclick=createWorking;refs.save.onclick=async()=>{if(await canDiscardPanelDraft()){clearPanelDraft();saveSituation()}};refs.del.onclick=async()=>{if(await canDiscardPanelDraft()){clearPanelDraft();deleteSituation()}};refs.tools.querySelectorAll('[data-mode]').forEach(b=>b.onclick=async()=>{if(await canDiscardPanelDraft()){clearPanelDraft();setMode(b.dataset.mode)}});refs.close.onclick=async()=>{if(await canDiscardPanelDraft()){clearPanelDraft();setInspectorOpen(false)}};refs.overviewTrigger.onclick=()=>{const open=!refs.overview.classList.contains('open');refs.overview.classList.toggle('open',open);refs.overviewTrigger.setAttribute('aria-expanded',String(open))};refs.fit.onclick=fitMap;refs.search.oninput=()=>{if(state.mode==='select')renderInspector()};window.addEventListener('beforeunload',e=>{if(state.dirty||state.panelDraftDirty){e.preventDefault();e.returnValue=''}})}
async function init(){try{state.me=await apiFetch('/api/me');const [a,r]=await Promise.all([apiFetch('/api/aircraft-types'),apiFetch('/api/resource-types')]);state.aircraft=a.items||[];state.resources=r.items||[];bind();await loadSituationList();await initMap();renderAll();if(state.list.length)await openSituation(state.list[0].situation_id)}catch(e){showMessage(errText(e),'error');renderAll()}}
init();
